// 単語：1行 = id|タイ文字|読み（ローマ字・声調記号つき）|日本語（主訳）|別の正解（/区切り）|品詞|分類|ヒント
// フレーズ：1行 = id|タイ文字|読み|日本語|別の言い方|場面|使い方の説明
// - 読みは学習者向けの表記：aa・ii などは長い母音、ɛ＝口を広く開けた「エ」、ɔ＝口を広く開けた「オ」、
//   ʉ＝唇を横に引いた「ウ」、ə＝あいまいな「ウ」。声調は記号なし＝平声、à＝低声、â＝下声、á＝高声、ǎ＝上声。
// - 丁寧に話すときは文末に、男性は ครับ（khráp）、女性は ค่ะ（khâ）を付ける。
// - 出典：日常会話の基本語を参考にした仮選定リスト（要確認）。
