export const LETTER_CATEGORIES = ['子音', '母音', '声調記号'];

export const THAI_LETTERS = LETTERS_RAW.trim().split('\n').map((line, i) => {
  const [id, letter, roman, ja, speak, cls, category, hint] = line.split('|');
  return {
    lang: 'th',
    kind: 'letter',
    // 同じ「ai」の音になる ไ と ใ は、選択肢に一緒に並べない
    similarGroup: ['tl71', 'tl72'].includes(id) ? 'tlg-ai' : '',
    id,
    es: letter,
    roman,
    ja,
    speak, // 読み上げは文字の名前（例：กอ ไก่）
    accepted: [ja, roman],
    pos: cls,
    article: '',
    category,
    hint: hint || '',
    stage: 1,
    level: 'A1',
    order: i + 1,
    source: '文字の名前と例の単語はタイの学校で使われる一般的なもの',
  };
});

// 意味が近く、選択肢に一緒に並べると正解が一つに決まらないフレーズのまとまり
const SIMILAR_GROUPS = [
  ['tp09', 'tp10'],
  ['tp20', 'tp24'],
  ['tp05', 'tp01'],
  ['tp06', 'tp08'],
  ['tp47', 'tp48', 'tp52'],
  ['tp42', 'tp43', 'tp44'],
];

const WORD_ROWS = WORDS_RAW.trim().split('\n');
export const THAI_WORD_STAGES = stagesFor(WORD_ROWS.length); // 行の順番でレベルに分ける（levels.js）

export const THAI_WORDS = WORD_ROWS.map((line, i) => {
  const [id, th, roman, ja, alts, pos, category, hint] = line.split('|');
  const stage = stageIdAt(THAI_WORD_STAGES, i + 1);
  return {
    lang: 'th',
    kind: 'word',
    id,
    es: th, // 学習する言語の表記（タイ文字）。項目名は全言語共通で es を使う
    roman,
    ja,
    accepted: [ja, ...(alts ? alts.split('/') : [])],
    pos,
    article: '',
    category,
    hint: hint || '',
    stage,
    level: THAI_WORD_STAGES.find((s) => s.id === stage).level,
    order: i + 1,
    frequencyRank: i + 1,
    source: THAI_SOURCE,
  };
});

export const THAI_PHRASES = PHRASES_RAW.trim().split('\n').map((line, i) => {
  const [id, th, roman, ja, alts, category, note] = line.split('|');
  const group = SIMILAR_GROUPS.findIndex((g) => g.includes(id));
  return {
    lang: 'th',
    similarGroup: group >= 0 ? `tpg${group}` : '',
    kind: 'phrase',
    id,
    es: th,
    roman,
    ja,
    accepted: [ja, ...(alts ? alts.split('/') : [])],
    category,
    hint: '',
    note: note || '',
    stage: 1,
    level: 'A1',
    order: i + 1,
    source: THAI_SOURCE,
  };
});
